/* Copy table as picture — standalone add-on (no dependency on any other project file).
   A small floating button appears while a table is on screen. Click it and the whole table
   (every row and column, not just the visible part) is copied to the clipboard as a PNG,
   ready to paste into Teams, WhatsApp, Outlook, Word, Excel…  If the browser blocks clipboard
   access, the PNG is downloaded instead.
   Presentation only: reads the page, never changes table content, values, events or exports. */
(function () {
  'use strict';

  /* Background icons used by the table styling (embedded so the picture never depends on file access). */
  const ICONS = {"bu_beauty.png": "data:image/png;base64,", "bu_foods.png": "data:image/png;base64,", "bu_home.png": "data:image/png;base64,", "bu_personal.png": "data:image/png;base64,", "cat_cookingaids.png": "data:image/png;base64,", "cat_fabriccleaning.png": "data:image/png;base64,", "cat_haircare.png": "data:image/png;base64,", "cat_homehygiene.png": "data:image/png;base64,", "cat_lifestylenutrition.png": "data:image/png;base64,", "cat_oralcare.png": "data:image/png;base64,", "cat_skincare.png": "data:image/png;base64,", "cat_skincleansing.png": "data:image/png;base64,"};

  const SVG_NS = 'http://www.w3.org/2000/svg';
  const PAD = 14;                 // white margin around the table in the picture
  const MAX_SIDE = 16000;         // px, canvas safety limit (Chrome/Edge allow 16 384)
  const MAX_AREA = 110e6;         // px², canvas safety limit

  /* Computed properties copied onto every cloned element (keeps the picture identical to the screen). */
  const PROPS = ['color', 'background-color', 'background-image', 'background-size', 'background-position', 'background-repeat',
    'border-top-width', 'border-top-style', 'border-top-color', 'border-right-width', 'border-right-style', 'border-right-color',
    'border-bottom-width', 'border-bottom-style', 'border-bottom-color', 'border-left-width', 'border-left-style', 'border-left-color',
    'border-top-left-radius', 'border-top-right-radius', 'border-bottom-right-radius', 'border-bottom-left-radius',
    'padding-top', 'padding-right', 'padding-bottom', 'padding-left', 'margin-top', 'margin-right', 'margin-bottom', 'margin-left',
    'font-family', 'font-size', 'font-weight', 'font-style', 'line-height', 'letter-spacing', 'text-transform', 'text-align',
    'text-decoration-line', 'text-overflow', 'vertical-align', 'white-space', 'word-break', 'overflow-wrap', 'font-variant-numeric',
    'display', 'visibility', 'opacity', 'overflow-x', 'overflow-y', 'box-shadow', 'border-collapse', 'border-spacing',
    'flex-direction', 'flex-wrap', 'flex-grow', 'flex-shrink', 'align-items', 'justify-content', 'gap',
    'grid-template-columns', 'grid-column-start', 'grid-column-end', 'column-gap', 'row-gap', 'direction'];
  const SIZED = { TD: 1, TH: 1 };
  const FALLBACK_FONT = ', "Segoe UI", system-ui, -apple-system, Roboto, Arial, sans-serif';

  /* ----------------------------------------------------------------------------------- rendering */
  function tooLarge(msg) { const e = new Error(msg); e.name = 'TableTooLarge'; return e; }

  function iconUrl(value) {                     // url("…/icons/x.png") → embedded data URI, anything else external → none
    return value.replace(/url\((['"]?)(.*?)\1\)/g, (m, q, u) => {
      if (u.slice(0, 5) === 'data:') return m;
      const name = decodeURIComponent(u.split(/[?#]/)[0].split('/').pop());
      return ICONS[name] ? 'url("' + ICONS[name] + '")' : 'none';
    });
  }

  function styleOf(el, pseudo) {
    const cs = getComputedStyle(el, pseudo || null);
    let out = '';
    for (let i = 0; i < PROPS.length; i++) {
      const p = PROPS[i];
      let v = cs.getPropertyValue(p);
      if (!v || v === 'normal' && p !== 'white-space' && p !== 'letter-spacing' && p !== 'line-height' && p !== 'word-break' && p !== 'overflow-wrap' && p !== 'font-variant-numeric') continue;
      if (p === 'background-image') { if (v === 'none') continue; v = iconUrl(v); if (v === 'none') continue; }
      if (p === 'font-family') v += FALLBACK_FONT;
      out += p + ':' + v + ';';
    }
    return out;
  }

  function pseudoText(el, which) {
    const cs = getComputedStyle(el, which);
    const c = cs.content;
    if (!c || c[0] !== '"' && c[0] !== "'") return null;
    const text = c.slice(1, -1).replace(/\\(.)/g, '$1');
    if (!text.trim() || cs.display === 'none') return null;
    let st = 'color:' + cs.color + ';font-size:' + cs.fontSize + ';font-weight:' + cs.fontWeight + ';letter-spacing:' + cs.letterSpacing +
      ';text-transform:' + cs.textTransform + ';line-height:' + cs.lineHeight + ';opacity:' + cs.opacity + ';';
    if (cs.display === 'block' || cs.display === 'inline-block') st += 'display:' + cs.display + ';margin-bottom:' + cs.marginBottom + ';margin-top:' + cs.marginTop + ';';
    st += 'margin-left:' + cs.marginLeft + ';margin-right:' + cs.marginRight + ';';
    return { text, style: st };
  }

  async function render(wrap, wantedScale) {
    const table = wrap.querySelector('table');
    if (!table || !table.rows.length) throw new Error('Nothing to copy');
    const bodyRows = Array.from(table.tBodies).reduce((a, b) => a + b.rows.length, 0);
    const tr0 = table.getBoundingClientRect();
    const tw = Math.ceil(tr0.width), th = Math.ceil(tr0.height);
    if (!tw || !th) throw new Error('Table is hidden');

    const wcs = getComputedStyle(wrap);
    const bw = parseFloat(wcs.borderTopWidth) || 0;
    const outW = tw + 2 * (PAD + bw), outH = th + 2 * (PAD + bw);
    let scale = Math.min(wantedScale || 2, MAX_SIDE / outW, MAX_SIDE / outH, Math.sqrt(MAX_AREA / (outW * outH)));
    if (scale < 1) {
      const fit = Math.max(1, Math.floor(bodyRows * (MAX_SIDE - 2 * (PAD + bw)) / th));
      throw tooLarge('This table is too long for one picture (' + bodyRows + ' rows; about ' + fit + ' fit). Filter it first, then copy again.');
    }

    const src = [table].concat(Array.from(table.querySelectorAll('*')));
    const clone = table.cloneNode(true);
    const dst = [clone].concat(Array.from(clone.querySelectorAll('*')));
    const classes = new Map();                     // identical style strings share one CSS class (keeps big tables small)
    let css = '';
    const cls = (s) => { let c = classes.get(s); if (!c) { c = 'tp' + classes.size; classes.set(s, c); css += '.' + c + '{' + s + '}\n'; } return c; };

    for (let i = 0; i < src.length; i++) {
      const s = src[i], d = dst[i];
      const tag = s.tagName;
      if (tag === 'SCRIPT' || tag === 'STYLE') { d.remove(); continue; }
      const cs = getComputedStyle(s);
      let extra = 'box-sizing:border-box;';
      if (cs.position === 'relative' || cs.position === 'absolute') {
        extra += 'position:' + cs.position + ';top:' + cs.top + ';left:' + cs.left + ';right:' + cs.right + ';bottom:' + cs.bottom + ';';
        if (cs.zIndex !== 'auto') extra += 'z-index:' + cs.zIndex + ';';
      }                                             // sticky → static (the picture is one flat image)
      if (cs.width !== 'auto' && (tag === 'SPAN' || tag === 'I' || tag === 'B' || tag === 'DIV' || tag === 'IMG' || tag === 'SVG') && cs.display !== 'inline') extra += 'width:' + cs.width + ';height:' + cs.height + ';';
      d.setAttribute('class', cls(styleOf(s) + extra));
      d.removeAttribute('style'); d.removeAttribute('id'); d.removeAttribute('data-label');
      if (SIZED[tag] && cs.display !== 'none') {    // pin every cell to its on-screen size so columns/rows match exactly
        const r = s.getBoundingClientRect();
        d.setAttribute('style', 'width:' + r.width + 'px;height:' + r.height + 'px;');
      }
      if (tag === 'TABLE') d.setAttribute('style', 'width:' + tw + 'px;');
      if (tag === 'INPUT') { if (s.checked) d.setAttribute('checked', 'checked'); d.setAttribute('value', s.value); }
      if (tag === 'IMG') {                          // data: images only (anything else would taint the picture)
        const u = s.getAttribute('src') || '';
        if (u.slice(0, 5) !== 'data:') { const n = decodeURIComponent(u.split(/[?#]/)[0].split('/').pop()); if (ICONS[n]) d.setAttribute('src', ICONS[n]); else d.removeAttribute('src'); }
        d.removeAttribute('srcset'); d.removeAttribute('loading');
      }
      if (!(tag === 'TH' && s.closest('thead'))) {  // text produced by CSS (the "–" for zero, phone-card labels) becomes real text
        ['::before', '::after'].forEach((w) => {
          const p = pseudoText(s, w); if (!p) return;
          const sp = document.createElement('span'); sp.setAttribute('style', p.style); sp.textContent = p.text;
          if (w === '::before') d.insertBefore(sp, d.firstChild); else d.appendChild(sp);
        });
      }
    }

    /* Card shell that mimics the on-screen table box */
    const doc = document.implementation.createHTMLDocument('');
    const root = doc.createElement('div');
    root.setAttribute('style', 'width:' + outW + 'px;height:' + outH + 'px;background:#fff;box-sizing:border-box;padding:' + PAD + 'px;');
    const style = doc.createElement('style'); style.textContent = css; root.appendChild(style);
    const box = doc.createElement('div');
    box.setAttribute('style', 'width:' + (tw + 2 * bw) + 'px;box-sizing:border-box;overflow:hidden;border:' + bw + 'px solid ' + wcs.borderTopColor + ';border-radius:' + wcs.borderTopLeftRadius + ';background:' + (wcs.backgroundColor === 'rgba(0, 0, 0, 0)' ? '#fff' : wcs.backgroundColor) + ';');
    box.appendChild(doc.importNode(clone, true));
    root.appendChild(box);

    let xhtml = new XMLSerializer().serializeToString(root).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
    const svg = '<svg xmlns="' + SVG_NS + '" width="' + outW + '" height="' + outH + '" viewBox="0 0 ' + outW + ' ' + outH + '"><foreignObject x="0" y="0" width="100%" height="100%">' + xhtml + '</foreignObject></svg>';

    const img = new Image();
    await new Promise((ok, bad) => {
      const t = setTimeout(() => bad(new Error('Rendering timed out')), 20000);
      img.onload = () => { clearTimeout(t); ok(); };
      img.onerror = () => { clearTimeout(t); bad(new Error('Could not render this table')); };
      img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    });
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(outW * scale); canvas.height = Math.round(outH * scale);
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    const blob = await new Promise((ok, bad) => canvas.toBlob((b) => (b ? ok(b) : bad(new Error('Could not create the image'))), 'image/png'));
    return { blob, width: canvas.width, height: canvas.height, scale, rows: bodyRows };
  }

  /* ------------------------------------------------------------------------------------ copy / save */
  function fileName() {
    const t = (document.title || 'Table').split('\u00b7')[0].trim().replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '') || 'Table';
    const d = new Date(), p = (n) => String(n).padStart(2, '0');
    return t + '_' + d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + '_' + p(d.getHours()) + p(d.getMinutes()) + '.png';
  }
  function download(blob) {
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = fileName();
    document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(a.href), 4000);
  }
  async function copy(wrap) {
    const job = render(wrap);
    job.catch(() => {});                                       // handled below
    if (navigator.clipboard && window.ClipboardItem && window.isSecureContext) {
      try {
        await navigator.clipboard.write([new ClipboardItem({ 'image/png': job.then((r) => r.blob) })]);
        return { how: 'clipboard', info: await job };
      } catch (e) { if (e && (e.name === 'TableTooLarge' || !/NotAllowed|Security|Type/i.test(e.name))) throw e; }
    }
    const r = await job; download(r.blob); return { how: 'file', info: r };
  }

  /* --------------------------------------------------------------------------------------- button */
  const CAM = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 8.5A2.5 2.5 0 0 1 6.5 6h1.2a1.5 1.5 0 0 0 1.3-.75l.4-.75A1.5 1.5 0 0 1 10.7 3.7h2.6a1.5 1.5 0 0 1 1.3.8l.4.75a1.5 1.5 0 0 0 1.3.75h1.2A2.5 2.5 0 0 1 20 8.5v8A2.5 2.5 0 0 1 17.5 19h-11A2.5 2.5 0 0 1 4 16.5z"/><circle cx="12" cy="12.5" r="3.4"/></svg>';
  const OK = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>';
  const CSS = '#tpWrap{position:fixed;left:50%;bottom:22px;z-index:63;transform:translate(-50%,14px);opacity:0;visibility:hidden;pointer-events:none;transition:opacity .18s,transform .18s,visibility .18s}' +
    '#tpWrap.on{transform:translate(-50%,0);opacity:1;visibility:visible;pointer-events:auto}' +
    '#tpBtn{display:flex;align-items:center;gap:7px;height:38px;padding:0 14px 0 11px;border-radius:999px;border:1px solid rgba(125,214,229,.32);background:#0f1d2e;color:#dff7f3;font:600 12px/1 "Plus Jakarta Sans","Segoe UI",system-ui,sans-serif;letter-spacing:.01em;cursor:pointer;' +
    'box-shadow:0 16px 38px -12px rgba(2,10,22,.65),0 0 0 4px rgba(20,184,166,.10);transition:background-color .15s,transform .1s,border-color .15s;white-space:nowrap}' +
    '#tpBtn svg{width:17px;height:17px;flex:none}#tpBtn:hover:not(:disabled){background:#1f8f86;border-color:#4fd4c6}#tpBtn:active:not(:disabled){transform:scale(.96)}' +
    '#tpBtn:disabled{cursor:progress;opacity:.75}#tpBtn:focus-visible{outline:2px solid #5eead4;outline-offset:2px}#tpBtn.done{background:#15803d;border-color:#4ade80}' +
    '#tpBtn.spin svg{animation:tpSpin .9s linear infinite}@keyframes tpSpin{to{transform:rotate(360deg)}}' +
    '#tpToast{position:absolute;left:50%;bottom:calc(100% + 10px);transform:translateX(-50%);max-width:min(88vw,340px);width:max-content;padding:9px 13px;border-radius:12px;background:#0f1d2e;color:#eaf4ff;font:600 12px/1.4 "Segoe UI",system-ui,sans-serif;' +
    'text-align:center;box-shadow:0 12px 30px -10px rgba(2,10,22,.7);opacity:0;visibility:hidden;pointer-events:none;transition:opacity .15s}#tpToast.on{opacity:1;visibility:visible}#tpToast.err{background:#7f1d1d}' +
    '[data-tp-target]{outline:2px solid #14b8a6!important;outline-offset:-2px;border-radius:12px}' +
    '@media(max-width:640px){#tpWrap{bottom:16px}#tpBtn{width:44px;height:44px;padding:0;justify-content:center}#tpBtn .tp-t{display:none}}' +
    '@media(prefers-reduced-motion:reduce){#tpWrap,#tpBtn{transition:none}#tpBtn.spin svg{animation:none}}@media print{#tpWrap{display:none!important}}';

  let wrapEl, btn, toast, active = null, hover = null, raf = 0, tmr = 0, busy = false, toastT = 0;

  function build() {
    const st = document.createElement('style'); st.id = 'tpStyle'; st.textContent = CSS; document.head.appendChild(st);
    wrapEl = document.createElement('div'); wrapEl.id = 'tpWrap';
    wrapEl.innerHTML = '<div id="tpToast" role="status" aria-live="polite"></div><button type="button" id="tpBtn" title="Copy this table as a picture" aria-label="Copy table as picture">' + CAM + '<span class="tp-t">Copy as picture</span></button>';
    document.body.appendChild(wrapEl);
    btn = wrapEl.querySelector('#tpBtn'); toast = wrapEl.querySelector('#tpToast');
    btn.addEventListener('pointerenter', () => { if (active) active.setAttribute('data-tp-target', ''); });
    btn.addEventListener('pointerleave', untarget);
    btn.addEventListener('blur', untarget);
    btn.addEventListener('click', onClick);
  }
  function untarget() { document.querySelectorAll('[data-tp-target]').forEach((e) => e.removeAttribute('data-tp-target')); }
  function say(msg, err) {
    toast.textContent = msg; toast.classList.toggle('err', !!err); toast.classList.add('on');
    clearTimeout(toastT); toastT = setTimeout(() => toast.classList.remove('on'), err ? 4500 : 2400);
  }
  async function onClick() {
    if (busy || !active) return;
    const w = active, label = btn.querySelector('.tp-t');
    busy = true; btn.disabled = true; btn.classList.add('spin'); toast.classList.remove('on');
    try {
      const r = await copy(w);
      btn.classList.remove('spin'); btn.classList.add('done'); btn.firstElementChild.outerHTML = OK;
      if (label) label.textContent = r.how === 'clipboard' ? 'Copied' : 'Saved';
      say(r.how === 'clipboard' ? 'Table copied as a picture (' + r.info.rows + ' rows). Paste it anywhere.' : 'Clipboard was blocked, so the picture was downloaded as a PNG file.');
    } catch (e) {
      say((e && e.message) || 'Could not copy this table.', true);
    } finally {
      busy = false; btn.disabled = false; btn.classList.remove('spin');
      setTimeout(() => {
        btn.classList.remove('done'); const ic = btn.firstElementChild; if (ic && ic.tagName.toLowerCase() === 'svg') ic.outerHTML = CAM;
        const l = btn.querySelector('.tp-t'); if (l) l.textContent = 'Copy as picture';
      }, 1800);
    }
  }

  function candidates() {
    const vw = innerWidth, vh = innerHeight, out = [];
    document.querySelectorAll('.table-wrap').forEach((w) => {
      const t = w.querySelector('table'); if (!t || !t.tBodies.length || !t.tBodies[0].rows.length) return;
      const r = w.getBoundingClientRect();
      const l = Math.max(r.left, 0), rt = Math.min(r.right, vw), top = Math.max(r.top, 0), b = Math.min(r.bottom, vh);
      if (rt - l < 80 || b - top < 70) return;
      const hit = document.elementFromPoint(l + (rt - l) / 2, top + (b - top) / 2);
      if (hit && !(w.contains(hit) || hit.closest('#tpWrap') || hit.closest('#tsDock'))) return;   // covered by drawer / overlay / menu
      out.push({ w, area: (rt - l) * (b - top), cx: (l + rt) / 2 });
    });
    return out;
  }

  function update() {
    raf = 0;
    if (!wrapEl) return;
    const c = candidates();
    let pick = null;
    if (hover) pick = c.find((x) => x.w === hover) || null;
    if (!pick && c.length) pick = c.reduce((a, b) => (b.area > a.area ? b : a));
    if (busy) return;                                           // keep the target steady while rendering
    if (!pick) { active = null; wrapEl.classList.remove('on'); return; }
    active = pick.w; wrapEl.classList.add('on');
    /* sit next to the floating scroll control when it is showing, otherwise centred on the table */
    const half = (wrapEl.offsetWidth || 150) / 2, dock = document.getElementById('tsDock');
    let cx = pick.cx;
    if (dock && dock.classList.contains('on')) {
      const d = dock.getBoundingClientRect();
      if (d.right + 10 + half * 2 <= innerWidth - 8) cx = d.right + 10 + half;
      else if (d.left - 10 - half * 2 >= 8) cx = d.left - 10 - half;
    }
    wrapEl.style.left = Math.min(Math.max(cx, half + 8), innerWidth - half - 8) + 'px';
  }
  const schedule = () => { if (!raf) raf = requestAnimationFrame(update); };
  const later = () => { clearTimeout(tmr); tmr = setTimeout(schedule, 250); };

  function init() {
    build();
    document.addEventListener('scroll', schedule, { capture: true, passive: true });
    window.addEventListener('resize', schedule, { passive: true });
    const pick = (e) => { const w = e.target.closest && e.target.closest('.table-wrap'); if (w && w !== hover) { hover = w; schedule(); } };
    document.addEventListener('pointerover', pick, { passive: true });
    document.addEventListener('touchstart', pick, { passive: true });
    new MutationObserver(later).observe(document.querySelector('main') || document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
    setInterval(schedule, 700);                                 // follows the floating scroll control as it appears / disappears
    schedule();
  }
  window.TablePicture = { render, copy };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
